create or replace function public.choose_account_plan(p_plan_id text,p_start_trial boolean default false) returns public.account_entitlements language plpgsql security definer set search_path=public as $$ declare v_user uuid:=auth.uid();v_row public.account_entitlements;v_now timestamptz:=now();v_end timestamptz;v_role text; begin if v_user is null then raise exception 'Authentication required';end if;if p_plan_id not in ('free','student','pro','champion','academy') then raise exception 'Invalid plan';end if;select * into v_row from public.account_entitlements where user_id=v_user for update;if p_start_trial then if p_plan_id='free' then raise exception 'The Free plan does not need a trial.';end if;if v_row.trial_claimed_at is not null then raise exception 'Your one-time trial has already been used.';end if;v_end:=v_now+interval '7 days';insert into public.account_entitlements(user_id,selected_plan_id,trial_claimed_at,trial_plan_id,trial_started_at,trial_ends_at,updated_at) values(v_user,p_plan_id,v_now,p_plan_id,v_now,v_end,v_now) on conflict(user_id) do update set selected_plan_id=excluded.selected_plan_id,trial_claimed_at=excluded.trial_claimed_at,trial_plan_id=excluded.trial_plan_id,trial_started_at=excluded.trial_started_at,trial_ends_at=excluded.trial_ends_at,updated_at=v_now returning * into v_row;insert into public.subscriptions(user_id,plan_id,provider,status,current_period_end) values(v_user,p_plan_id,'manual','trialing',v_end) on conflict(user_id) do update set plan_id=excluded.plan_id,provider='manual',status='trialing',current_period_end=v_end,updated_at=v_now;else if p_plan_id<>'free' then raise exception 'A paid plan requires an active trial or authorized billing.';end if;insert into public.account_entitlements(user_id,selected_plan_id,updated_at) values(v_user,'free',v_now) on conflict(user_id) do update set selected_plan_id='free',updated_at=v_now returning * into v_row;update public.subscriptions set status='canceled',current_period_end=v_now,updated_at=v_now where user_id=v_user and status='trialing';end if;v_role:=case when p_plan_id='champion' then 'coach' when p_plan_id='academy' then 'academy_admin' when p_plan_id in ('free','student','pro') then 'athlete' end;if v_role is not null then update public.profiles set plan_id=p_plan_id,role=v_role where user_id=v_user and role not in ('support_admin','admin','super_admin');end if;return v_row;end;$$;

create or replace function public.change_account_plan(p_plan_id text) returns public.account_entitlements language plpgsql security definer set search_path=public as $$ declare v_user uuid:=auth.uid();v_row public.account_entitlements;v_now timestamptz:=now();v_role text;begin if v_user is null then raise exception 'Authentication required';end if;if p_plan_id not in ('free','student','pro','champion','academy') then raise exception 'Invalid plan';end if;select * into v_row from public.account_entitlements where user_id=v_user for update;if not found then raise exception 'Choose your account plan first.';end if;if p_plan_id='free' then update public.account_entitlements set selected_plan_id='free',updated_at=v_now where user_id=v_user returning * into v_row;update public.subscriptions set status='canceled',current_period_end=v_now,updated_at=v_now where user_id=v_user and status='trialing';else if v_row.trial_claimed_at is null or v_row.trial_ends_at is null or v_row.trial_ends_at<=v_now then raise exception 'Your one-time trial is not active.';end if;update public.account_entitlements set selected_plan_id=p_plan_id,trial_plan_id=p_plan_id,updated_at=v_now where user_id=v_user returning * into v_row;update public.subscriptions set plan_id=p_plan_id,updated_at=v_now where user_id=v_user and status='trialing';end if;v_role:=case when p_plan_id='champion' then 'coach' when p_plan_id='academy' then 'academy_admin' when p_plan_id in ('free','student','pro') then 'athlete' end;if v_role is not null then update public.profiles set plan_id=p_plan_id,role=v_role where user_id=v_user and role not in ('support_admin','admin','super_admin');end if;return v_row;end;$$;
